package net.civeira.phylax.feature.observe.observedalertrule.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedalertrule.domain.ObservedAlertRule;
import net.civeira.phylax.feature.observe.observedalertrule.domain.valueobject.TargetVO;

class TargetValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of target of observed alert rule")
  void test_target_value_holder_assign_plain_value() {
    Object holder = new Object();
    TargetValueHolder<Object> value = new TargetValueHolder<>(holder);
    Assertions.assertSame(holder, value.target("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getTargetValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getTarget().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.targetNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getTargetValue().isPresent(), "A null value object must be stored");
    Assertions.assertFalse(value.getTarget().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of target of observed alert rule")
  void test_target_value_holder_assign_value_object() {
    Object holder = new Object();
    TargetValueHolder<Object> value = new TargetValueHolder<>(holder);
    TargetVO vo = TargetVO.from("one");
    Assertions.assertFalse(value.getTargetValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.target(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getTargetValue().orElseThrow());
    Assertions.assertSame(holder, value.target(Optional.empty()));
    Assertions.assertFalse(value.getTargetValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.target(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTargetValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of target of observed alert rule against the original")
  void test_target_value_holder_read() {
    Object holder = new Object();
    TargetValueHolder<Object> value = new TargetValueHolder<>(holder);
    TargetVO vo = TargetVO.from("one");
    TargetVO other = TargetVO.from("one");
    ObservedAlertRule original = Mockito.mock(ObservedAlertRule.class);
    Mockito.when(original.getTargetValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readTarget(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readTarget(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.target(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readTarget(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readTarget(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of target of observed alert rule")
  void test_target_value_holder_unset() {
    Object holder = new Object();
    TargetValueHolder<Object> value = new TargetValueHolder<>(holder);
    TargetVO vo = TargetVO.from("one");
    value.target(vo);
    Assertions.assertSame(holder, value.unsetTargetIfMatches("target_other"));
    Assertions.assertTrue(value.getTargetValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetTargetIfMatches("target"));
    Assertions.assertFalse(value.getTargetValue().isPresent(),
        "The field name must clear the value");
    value.target(vo);
    Assertions.assertSame(holder, value.unsetTarget());
    Assertions.assertFalse(value.getTargetValue().isPresent(), "Unset must clear the value");
  }
}
